;---------------------------------------------------------------------------------------------------
; CalculateKnockRetard_MM  ($AD00)
;
; Knock detection: compares the knock sample with the background average (main loop). [reviewed -
; data flow]
;
; Knock is declared when KnockVolts exceeds the running average (CalculateAverageKnockVolts_SM) by
; DLTKNK (vs RPM, MAP above KNKMAP and RPM above KNKRPM). The total retard is limited by RETMAX
; (vs MAP). The per-cylinder retard itself is updated in the crank interrupt
; (CALC_SPARK_RETARD_BASED_ON_KNOCK_VOLT: rate RTRDRT, recovery INCSRT, limit MAXRTD per cylinder)
; and its sum also drives the knock enrichment of the fuel (KNNRCH).
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
CalculateKnockRetard_MM:
        clra
        ldab    <EngineRpm_HB
        cmpb    >KNKRPM_MinRpmforKnockRetard         ; KNKRPM: Minimum RPM for Knock Retard
        bcs     LAD07
        deca
        ldab    <b58_IPL1
        andb    #$E0
        bne     LAD01
        ldaa    <MapValue
        ldab    <TpsVolts
        subb    <MINTHR_LowestSessionTPS
        bcs     LAD01
        cmpb    >THRKNK_DeltaAbove_MINTHR            ; THRKNK: Delta above MINTHR for knock detect
        bcs     LAD01
        ldab    <EngineRpm_HB
        cmpb    >KLMRPM_MinKnockDetectRpm            ; KLMRPM: RPMS for Knock
        bcc     LAD01
        ldaa    >KNKLIM_MaxKnockRetard               ; KNKLIM: Knock Limit in 1/2 degrees. MaxRetard = KNKLIM if throttle is above TH
        bra     LAD07

LAD01:
        ldx     #RETMAX_MaxKnockRetardFromMap        ; RETMAX: Maximum Knock Retard from Map
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
LAD07:
        staa    <Var_00CA
        ldaa    <EngineRpm_HB
        ldx     #DLTKNK_KnockSensorVoltageForKnockFromRpm ; DLTKNK: Input from the knock sensor that is above this voltage is considered K
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        adda    <AverageKnockVolts
        bcc     LAD17
        ldaa    #$FF
LAD17:
        staa    <KnockSensorThreshold
        ldaa    >INCSRT_KnockRetardIncreaseRate      ; INCSRT: Increase Rate. Recovery from Knock Retard. Rate is 1/2 engine degree e
        bita    <Counter_MainLoop
        bne     LAD27
        ldaa    <KnockRetardSum_AllCyls
        beq     LAD27
        deca
        staa    <KnockRetardSum_AllCyls
LAD27:
        brset   <BitFlags71,#$80,LAD7E
        ldaa    <CoolantTemp
        cmpa    >ARMINT_AdaptiveRetardMinimumTemp    ; ARMINT (AdaptiveRetardMinimumTemp)
        bls     LAD6D
        ldaa    <MapValue
        cmpa    >ARMPIC_AdaptiveRetard_MinMAPForAdjustment ; ARMPIC: ff disables the Adaptive Knock Retard
        bcs     LAD6D
        ldab    <KnockRetardSum_AllCyls
        aslb
        bcs     LAD41
        aslb
        bcc     LAD43
LAD41:
        ldab    #$FF
LAD43:
        tstb
        beq     LAD6D
        ldaa    <Counter_MainLoop
        anda    >ARCMSK_AdaptiveRetardCounterMask    ; ARCMSK (AdaptiveRetardCounterMask)
        bne     LAD7E
        ldaa    <Timer_Over5PsiBoostMaxFF
        inca
        cmpa    >ARTM5P_AdaptiveRetardTimeOver5psiBoost ; ARTM5P (AdaptiveRetardTimeOver5psiBoost)
        bcs     LAD7C
        cmpb    >TOTKRT_TotalKnockRetardRef          ; TOTKRT (TotalKnockRetardRef)
        bls     LAD7C
        sei
        brset   <b59_IPL2,#$01,LAD66
        ldab    <AdaptiveRetardIndex
        addb    >ARINDX_AdaptiveRetardIndexBase_80   ; ARINDX (AdaptiveRetardIndexBase_80)
        bcc     LAD68
LAD66:
        ldab    #$FF
LAD68:
        stab    <AdaptiveRetardIndex
        cli
        bra     LAD7B

LAD6D:
        ldaa    <Counter_MainLoop
        bita    >ARCMS2_AdaptiveRetardCounterMask2_00 ; ARCMS2 (AdaptiveRetardCounterMask2_00)
        bne     LAD7E
        ldaa    <Timer_Over5PsiBoostMaxFF
        suba    >ARCMS3_AdaptiveRetardCounterMask3_FF ; ARCMS3 (AdaptiveRetardCounterMask3_FF)
        bcc     LAD7C
LAD7B:
        clra
LAD7C:
        staa    <Timer_Over5PsiBoostMaxFF
LAD7E:
        rts


;---------------------------------------------------------------------------------------------------
; CalculateAverageKnockVolts_SM  ($ADA6)
;
; Running average of the knock sensor background level (window: KNAMAP, KNARPM, KNACLT ...). [from
; name]
;
; Called from: SubLoopB
;---------------------------------------------------------------------------------------------------
CalculateAverageKnockVolts_SM:
        ldaa    <MapValue
        cmpa    >KNAMAP_MinMAPForAverageKnockVoltCalc ; KNAMAP (MinMAPForAverageKnockVoltCalc)
        bcc     LADCC
        ldaa    <EngineRpm_HB
        cmpa    >KNARPM_MinRPMForAverageKnockVoltCalc ; KNARPM (MinRPMForAverageKnockVoltCalc)
        bls     LADCC
        cmpa    >KNARPX_MaxRPMForAverageKnockVoltCalc ; KNARPX (MaxRPMForAverageKnockVoltCalc)
        bcc     LAE0C
        ldaa    <CoolantTemp
        cmpa    >KNACLT_MinCoolantTempForAverageKnockVoltCalc ; KNACLT (MinCoolantTempForAverageKnockVoltCalc)
        bls     LAE0C
        ldaa    <ChargeTemp
        cmpa    >KNAIAT_MinChargeTempForAverageKnockVoltCalc ; KNAIAT (MinChargeTempForAverageKnockVoltCalc)
        bcc     LAE0C
        brset   <BitFlags71,#$02,LAE0C
        ldaa    <KeyOnOrEngineRunningTime
        cmpa    >KNAERT_MinEngRunTImeForAverageKnockVoltCalc ; KNAERT (MinEngRunTImeForAverageKnockVoltCalc)
        bls     LAE0C
        ldaa    <Counter_KnockVoltsAvg
        bne     LAE0C
        ldaa    <TpsVolts
        tab
        suba    >Knock_0191
        bpl     LADB8
        nega
LADB8:
        cmpa    >KNATPS_MinThrotPosForAverageKnockVoltCalc ; KNATPS (MinThrotPosForAverageKnockVoltCalc)
        bcc     LAE0C
        subb    >Knock_0193
        bpl     LADC3
        negb
LADC3:
        cmpb    >KNATPS_MinThrotPosForAverageKnockVoltCalc ; KNATPS (MinThrotPosForAverageKnockVoltCalc)
        bcc     LAE0C
        brclr   <b58_IPL1,#$A0,LADCE
LADCC:
        bra     LAE0C

LADCE:
        bset    <IPL1,#$04
        ldaa    >KNADFT_DefaultKnockVoltsAverage     ; KNADFT (DefaultKnockVoltsAverage)
        bne     LADDB
        ldaa    <KnockVolts
        clrb
        bra     LADF2

LADDB:
        ldy     <AverageKnockVolts
        jsr     >ScaleYbyA                           ; D = Y x A / 256 (unsigned fractional multiply).
        pshy
        ldaa    <KnockVolts
        ldab    >KNADFT_DefaultKnockVoltsAverage     ; KNADFT (DefaultKnockVoltsAverage)
        mul
        tsy
        subd    $00,y
        puly
        addd    <AverageKnockVolts
LADF2:
        std     <AverageKnockVolts
        cmpa    >KNAMAX_MaxAverageKnockVolts         ; KNAMAX (MaxAverageKnockVolts)
        bls     LADFF
        ldaa    >KNAMAX_MaxAverageKnockVolts         ; KNAMAX (MaxAverageKnockVolts)
        clrb
        bra     LAE08

LADFF:
        cmpa    >KNAMIN_MinAverageKnockVolts         ; KNAMIN (MinAverageKnockVolts)
        bcc     LAE08
        ldaa    >KNAMIN_MinAverageKnockVolts         ; KNAMIN (MinAverageKnockVolts)
        clrb
LAE08:
        std     <AverageKnockVolts
        bra     LAE0F

LAE0C:
        bclr    <IPL1,#$04
LAE0F:
        rts


