;---------------------------------------------------------------------------------------------------
; Isr_TOC4_KnockSample  ($AE44)  -- interrupt vector: TOC4
;
; Output compare 4 interrupt: samples the knock sensor at the end of the knock window. [reviewed -
; partially]
;
; Starts an A/D conversion on channel 3, waits a few cycles and stores ADR1 in KnockVolts (or zero
; when knock sensing is disabled by BitFlags71 bit 7). The value feeds CalculateKnockRetard_MM.
;---------------------------------------------------------------------------------------------------
Isr_TOC4_KnockSample:
        brclr   <BitFlags71,#$80,LAE24
        clra
        bra     LAE31

LAE24:
        ldaa    #$03
        staa    >ADCTL
        ldab    #$07
LAE2B:
        decb
        bne     LAE2B
        ldaa    >ADR1
LAE31:
        staa    <KnockVolts
        ldx     #$0400
        bclr    $03,x,#$08
        ldaa    #$10
        staa    >TFLG1
        rti


