MonitorMisfire:
        ldaa    <BitFlagsE5
        anda    #$F7
        staa    <BitFlagsE5
        ldab    >ObdStatusFlags
        bitb    #$01
        beq     LAE50
        oraa    #$08
        staa    <BitFlagsE5
LAE50:
        ldaa    >ObdMonStatus_Misfire
        anda    #$10
        bne     LAE5A
        bclr    <BitFlagsE5,#$20
LAE5A:
        ldaa    >StartCoolantTemp
        cmpa    >LCBE0
        bcc     LAE65
        bset    <BitFlagsE5,#$04
LAE65:
        adda    >LCBDF
        bcc     LAE6C
        ldaa    #$FF
LAE6C:
        cmpa    <CoolantTemp
        bcc     LAE73
        bclr    <BitFlagsE5,#$04
LAE73:
        ldaa    >MisfireEventCount
        cmpa    #$64
        bcc     LAE7D
        jmp     >LAF21

LAE7D:
        ldaa    >MisfireCount100
        cmpa    >LCBD2
        bls     LAEBB
        bset    <BitFlagsE5,#$01
        sei
        ldaa    <MisfireCylBits
        anda    #$F0
        oraa    <MisfireCylConfirmed
        staa    <MisfireCylConfirmed
        ldaa    >ObdMonStatus_Misfire
        oraa    #$49
        staa    >ObdMonStatus_Misfire
        ldaa    >ObdStatusFlags
        oraa    #$10
        staa    >ObdStatusFlags
        ldaa    >MisfireCondFlags
        oraa    #$80
        staa    >MisfireCondFlags
        ldaa    #$80
        staa    >MisfireCondCount
        clra
        staa    >MisfireHealEvents
        staa    >MisfireHealCount
        staa    >MisfireHealBlocks
        staa    >MisfireHealSum
LAEBB:
        bclr    <MisfireCylBits,#$F0
        ldaa    >MisfireSum500
        adda    >MisfireCount100
        bcc     LAEC8
        ldaa    #$FF
LAEC8:
        staa    >MisfireSum500
        cli
        ldab    >MisfireBlockCount
        incb
        stab    >MisfireBlockCount
        cmpb    #$05
        bcs     LAF1A
        cmpa    >LCBD3
        bls     LAF11
        sei
        ldaa    <MisfireCylBits
        oraa    <MisfireCylConfirmed
        staa    <MisfireCylConfirmed
        ldaa    >ObdMonStatus_Misfire
        oraa    #$48
        ldab    >MisfireCondCount
        andb    #$80
        brclr   <BitFlagsE5,#$20,LAEF5
        oraa    #$01
        orab    #$80
LAEF5:
        staa    >ObdMonStatus_Misfire
        stab    >MisfireCondCount
        ldaa    >MisfireCondFlags
        oraa    #$80
        staa    >MisfireCondFlags
        cli
        clra
        staa    >MisfireHealEvents
        staa    >MisfireHealCount
        staa    >MisfireHealBlocks
        staa    >MisfireHealSum
LAF11:
        clra
        staa    <MisfireCylBits
        staa    >MisfireBlockCount
        staa    >MisfireSum500
LAF1A:
        clra
        staa    >MisfireEventCount
        staa    >MisfireCount100
LAF21:
        ldaa    >MisfireCondFlags
        anda    #$80
        bne     LAF2B
        jmp     >LAF9D

LAF2B:
        ldaa    >MisfireCondCount
        cmpa    #$80
        bne     LAF35
        jmp     >LAFAA

LAF35:
        ldaa    >MisfireHealEvents
        cmpa    #$64
        bcs     LAF95
        ldaa    >MisfireHealCount
        cmpa    >LCBD2
        bls     LAF49
        ldab    #$80
        stab    >MisfireCondCount
LAF49:
        inc     >MisfireHealBlocks
        sei
        ldaa    >MisfireHealSum
        adda    >MisfireHealCount
        bcc     LAF57
        ldaa    #$FF
LAF57:
        staa    >MisfireHealSum
        cli
        ldaa    >MisfireHealBlocks
        cmpa    #$05
        bcs     LAF8E
        ldab    >MisfireCondCount
        ldaa    >MisfireHealSum
        cmpa    >LCBD3
